CASE hms_Step OF
0 :
CS1030_config_hms.idle 	:= 100;
CS1030_config_hms.delimc	:= 0;
CS1030_config_hms.delim[0]  := 0;
CS1030_config_hms.delim[1]  := 0;
CS1030_config_hms.tx_cnt	:= 2;
CS1030_config_hms.rx_cnt	:= 2;
CS1030_config_hms.tx_len	:= 255;
CS1030_config_hms.rx_len	:= 255;
CS1030_config_hms.argc	:= 0;
CS1030_config_hms.argv	:= 0;
FRM_xopen_hms(enable := TRUE,device := ADR(PLC_node_address),mode := ADR('/BD=19200 /PA=N /DB=8 /SB=1 /PHY=RS485'),config := ADR(CS1030_config_hms));
IF (FRM_xopen_hms.status = 0) THEN
FRM_xopen_hms.enable	:= 0;
hms_Step := 5;
ELSIF (FRM_xopen_hms.status = frmERR_DEVICEDESCRIPTION) THEN
hms_Step := 100;
ELSE
hms_Step := 0;
END_IF
5:
hms_sendbuffer_length := 8;
hms_sendbuffer[0] := 254;
hms_sendbuffer[1] := 01;
hms_sendbuffer[2] := 03;
hms_sendbuffer[3] := 08;
hms_sendbuffer[4] := 00;
hms_sendbuffer[5] := 00;
checksum := 255;
FOR K := 0 TO 7 BY 1 DO
checksum := checksum XOR ((hms_sendbuffer[K]));
END_FOR;
hms_sendbuffer[6] := checksum;
hms_sendbuffer[7] := 253;
FRM_gbuf_hms(enable := TRUE, ident := FRM_xopen_hms.ident);
send_buffer	:= FRM_gbuf_hms.buffer;
IF (FRM_gbuf_hms.status = 0) THEN
FRM_gbuf_hms.enable := 0;
memcpy(send_buffer, ADR(hms_sendbuffer), FRM_gbuf_hms.buflng);
FRM_write_hms(enable := TRUE, ident := FRM_xopen_hms.ident, buffer := send_buffer, buflng := hms_sendbuffer_length);
IF (FRM_write_hms.status = 0) THEN
FRM_write_hms.enable := FALSE;
hms_Step := 10;
ELSE
FRM_robuf_hms(enable := TRUE, ident := FRM_xopen_hms.ident, buffer := FRM_write_hms.buffer, buflng := FRM_write_hms.buflng);
FRM_write_hms.enable := FALSE;
FRM_robuf_hms.enable := FALSE;
hms_Step := 5;
END_IF
ELSE
hms_Step := 5;
END_IF
10:
FRM_read_hms(enable := TRUE, ident := FRM_xopen_hms.ident);
read_buffer := FRM_read_hms.buffer;
hms_readbuffer_length := FRM_read_hms.buflng;
IF (FRM_read_hms.status = 0) THEN
memcpy(ADR(hms_readbuffer), read_buffer, hms_readbuffer_length);
IF ((hms_readbuffer[0]=hms_sendbuffer[0]) AND (hms_readbuffer[1]=1)) THEN
no_reply_count := 0;
rs_rcv_resolution := ((hms_readbuffer[4] * 100) + hms_readbuffer[5]) /1000;
rs_rcv_buffer_S1[1] := ((hms_readbuffer[22] * 256) + hms_readbuffer[23]) ;
rs_rcv_buffer_S1[2] := ((hms_readbuffer[24] * 256) + hms_readbuffer[25]) ;
rs_rcv_buffer_S1[3] := ((hms_readbuffer[26] * 256) + hms_readbuffer[27]) ;
rs_rcv_buffer_S1[4] := ((hms_readbuffer[28] * 256) + hms_readbuffer[29]) ;
rs_rcv_buffer_S1[5] := ((hms_readbuffer[30] * 256) + hms_readbuffer[31]) ;
rs_rcv_buffer_S1[6] := ((hms_readbuffer[32] * 256 )+ hms_readbuffer[33]) ;
rs_rcv_buffer_S1[7] := ((hms_readbuffer[34] * 256) + hms_readbuffer[35]) ;
rs_rcv_buffer_S1[8] := ((hms_readbuffer[36] * 256) + hms_readbuffer[37]) ;
rs_rcv_buffer_S1[9] :=  ((hms_readbuffer[6] * 256) + hms_readbuffer[7]) ;
rs_rcv_buffer_S1[10] := ((hms_readbuffer[8] * 256) + hms_readbuffer[9]) ;
rs_rcv_buffer_S1[11] := ((hms_readbuffer[10] * 256) + hms_readbuffer[11]) ;
rs_rcv_buffer_S1[12] := ((hms_readbuffer[12] * 256) + hms_readbuffer[13]) ;
rs_rcv_buffer_S1[13] := ((hms_readbuffer[14] * 256) + hms_readbuffer[15]) ;
rs_rcv_buffer_S1[14] := ((hms_readbuffer[16] * 256) + hms_readbuffer[17]) ;
rs_rcv_buffer_S1[15] := ((hms_readbuffer[18] * 256) + hms_readbuffer[19]) ;
rs_rcv_buffer_S1[16] := ((hms_readbuffer[20] * 256) + hms_readbuffer[21]) ;
END_IF
hms_Step := 5;
ELSIF (FRM_read_hms.status >= 60) THEN
read_wait_timer_en := TRUE;
END_IF
FRM_rbuf_hms(enable := TRUE, ident := FRM_xopen_hms.ident, buffer := read_buffer, buflng := hms_readbuffer_length);
IF (read_wait_timer.Q) THEN
hms_Step := 100;
no_reply_count := no_reply_count + 1;
END_IF
100:
FRM_close_hms(enable := TRUE, ident := FRM_xopen_hms.ident);
read_wait_timer_en := FALSE;
IF (FRM_close_hms.status = 0) THEN
hms_Step := 0;
ELSE
hms_Step := 100;
END_IF
END_CASE

