IF EDGEPOS(CALIB)THEN
DEAD_WEIGHT:=0;
AI_ref1_wt :=0;
AI_ref2_wt := 0;
AI_ref_tare:= 0;
REF_WT2:=0;
REF_WT1:=0;
STD1_DONE := 51;
STD2_DONE := 51;
STDTARE_DONE:=51;
WGHscale_2.raw_value := 0;
END_IF

IF(CALIB) THEN
MIN_WT := REF_WT1*1000;
MAX_WT := REF_WT2*1000;
LAP_WEIGHT_MEASURING_ENABLE := 1;
TEST_VAR.ref1_std := REAL_TO_DINT (MIN_WT);
TEST_VAR.ref2_std := REAL_TO_DINT (MAX_WT);
WGHscale_2(enable:=LAP_WEIGHT_MEASURING_ENABLE, doTare:=TARE, doStandardize1:=STD1, doStandardize2:=STD2, raw_value:=LOAD_CELL_ANALOG_VALUE, t_measure:=T#1s, pWGHscalePara:= ADR(TEST_VAR));
AI_ref1_wt := TEST_VAR.ref1_raw;
AI_ref2_wt := TEST_VAR.ref2_raw;
AI_ref_tare:= TEST_VAR.tare_std;
END_IF

IF((LAP_EJECTION1=0) AND (DI_LAP_PRESENT)) THEN
LOADCELL_CONDN:=1;
END_IF;

